+    }
+
+    sb.append("\nMAIN:\n");
+    sb.append(block.toString());
+    return sb.toString();
+  }
+
+  public SEXP evaluate() throws IOException {
+    Context context = Context.newTopLevelContext();
+    context.init();
+    return block.evaluate(context);
+  }
