+import r.lang.Context;
+import r.lang.Logical;
+import r.lang.SEXP;
+
+public class IfStatement implements Statement {
+
+  private SimpleExpr condition;
+  private IRLabel trueTarget;
+  private IRLabel falseTarget;
+
+  public IfStatement(SimpleExpr condition, IRLabel trueTarget, IRLabel
falseTarget) {
+    this.condition = condition;
+    this.trueTarget = trueTarget;
+    this.falseTarget = falseTarget;
+  }
+
+  public SimpleExpr getCondition() {
+    return condition;
+  }
+
+  public IRLabel getTrueTarget() {
+    return trueTarget;
+  }
+
+  public IRLabel getFalseTarget() {
+    return falseTarget;
+  }
+
+  @Override
+  public Object interpret(Context context, Object[] temp) {
+    boolean conditionalValue =  toBoolean(condition.retrieveValue(context,
temp));
+    if(conditionalValue) {
+      return trueTarget;
+    } else {
+      return falseTarget;
+    }
+  }
+
+  private boolean toBoolean(Object obj) {
+    if(obj instanceof Boolean) {
+      return (Boolean)obj;
+    } else if(obj instanceof SEXP) {
+      return ((SEXP)obj).asLogical() == Logical.TRUE;
+    } else {
+      throw new IllegalArgumentException(""+obj);
+    }
+  }
+
+  @Override
+  public String toString() {
+    return "if " + condition + " goto " + trueTarget + " else " +
falseTarget;
+  }
+}
