+    eval("stringInstance<-CallJavaFromRTest$new(stringValue)");
+    assertThat(
+        eval("if(stringInstance$stringConverted==stringValue) TRUE else
FALSE"),
+        logicalVectorOf(Logical.TRUE));
+  }
+
